trial.program_source:
def transform(grid):
    h=len(grid); w=len(grid[0]); out=[r[:] for r in grid]; seen=set(); lines=[]
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r,c) in seen: continue
            color=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            if len({y for y,x in comp})==1: lines.append(comp)
    if lines:
        chosen=min(lines,key=lambda a:min(a))
        for y,x in chosen: out[y][x]=5
    return out

